xml.Script:
        clWhite  := 'F0F0F0';
        clBlack  := '414141';
        clBlue   := '33BBFF';
        clYellow := 'E0E930';

        W  := 0.55;
        include 'Figures\Scripts\Snub_Cube_Coordinates.inc';

        W0 := W;
        W1 := W * 0.95;
        D := C2^2 / sqrt(C0^2 + C1^2 + C2^2);

        C6 := (C0 + C1) / 2;
        C7 := (C1 + C2) / 2;
        C8 := (C2 + C0) / 2;
        S0 := C0 * 0.95;
        S1 := C1 * 0.95;
        S2 := C2 * 0.95;

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          tx := y1 * z2 - y2 * z1;
          ty := z1 * x2 - z2 * x1;
          tz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((tx*wx + ty*wy + tz*wz) / (tx^2 + ty^2 + tz^2));
        end;

        A1 := Angle( C2,-C0, C1,  C2, C1, C0,  C2,-C1,-C0);
        A2 := Angle( C2,-C0, C1,  C2, C1, C0,  C1, C0, C2);
        A3 := A2*2;
        A4 := A2*3;

        procedure SetColor(Color);
        begin
            for i := 0 to 37 do
                Colors[i] := Color;
        end;
